svg.script:

function injectLogo() {
  const container = document.getElementById('logo-container');

  if (container) {
    const logo = document.createElementNS('http://www.w3.org/1999/xhtml', 'iframe');

    logo.setAttribute('src', 'https://cdn.jsdelivr.net/gh/unicyclevryt-tech/unizz-1@aa4b1d7d7bcbf76c8c550f15f45b7a285b68d483/tuff-view-2-386uxl.svg');
    logo.style.width = '100%';
    logo.style.height = '100%';
    logo.style.border = 'none';
    logo.style.background = 'white';
    logo.style.margin = '0';
    logo.style.padding = '0';

    container.appendChild(logo);
  }
}
